definition.script:
pipeline {
    agent {
        kubernetes {
            yaml '''
apiVersion: v1
kind: Pod
metadata:
  labels:
    some-label: jenkins-nginx-agent
spec:
  containers:
  - name: helm-kubectl
    image: dtzar/helm-kubectl:3.12.0
    command:
    - cat
    tty: true
'''
        }
    }
    stages {
        stage('Add Helm repository') {
            steps {
                container('helm-kubectl') {
                    sh 'helm repo add bitnami https://charts.bitnami.com/bitnami'
                    sh 'helm repo update'
                }
            }
        }
        stage('Install Nginx') {
            steps {
                container('helm-kubectl') {
                    sh '''
                    helm upgrade --install demo-nginx bitnami/nginx \
                      --set service.type=NodePort \
                      --namespace jenkins \
                      --set persistence.enabled=true \
                      --set staticSitePVC="rbd-pvc-nginx-jenkins" \
                      --set persistence.storageClass="rook-ceph-block" \
                      --set persistence.size=1Gi \
                      --set volumePermissions.enabled=true \
                      --set service.nodePorts.http=30080 \
                      --set serverBlock="server { listen 8080; location / { root /app; autoindex on; } }"
                     '''
                }
            }
        }
        stage('Veryfiy installation') {
            steps {
                container('helm-kubectl') {
                    sh 'kubectl get pods,svc -l app.kubernetes.io/name=nginx -n jenkins'
                }
            }
        }
    }
}
